// HasBackupProxy applies the HasEdge predicate on the "backup_proxy" edge.
func HasBackupProxy() predicate.OutboundProxy {
	return predicate.OutboundProxy(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, BackupProxyTable, BackupProxyColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBackupProxyWith applies the HasEdge predicate on the "backup_proxy" edge with a given conditions (other predicates).
func HasBackupProxyWith(preds ...predicate.OutboundProxy) predicate.OutboundProxy {
	return predicate.OutboundProxy(func(s *sql.Selector) {
		step := newBackupProxyStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasBackupFor applies the HasEdge predicate on the "backup_for" edge.
func HasBackupFor() predicate.OutboundProxy {
	return predicate.OutboundProxy(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, true, BackupForTable, BackupForColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBackupForWith applies the HasEdge predicate on the "backup_for" edge with a given conditions (other predicates).
func HasBackupForWith(preds ...predicate.OutboundProxy) predicate.OutboundProxy {
	return predicate.OutboundProxy(func(s *sql.Selector) {
		step := newBackupForStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OutboundProxy) predicate.OutboundProxy {
	return predicate.OutboundProxy(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OutboundProxy) predicate.OutboundProxy {
	return predicate.OutboundProxy(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OutboundProxy) predicate.OutboundProxy {
	return predicate.OutboundProxy(sql.NotPredicates(p))
}
